-- Jalankan sekali di Supabase SQL Editor untuk menambahkan tes Kana ke Part 13–15.
-- Part 13 = Tes Hiragana, Part 14 = Tes Katakana, Part 15 = Tes gabungan.
-- Script aman dijalankan ulang: Part diperbarui berdasarkan nomor, soal tidak diduplikasi berdasarkan prompt.
do $$
declare
  v_id uuid;
  v_part record;
begin
  select id into v_id from public.parts where part_number = 13 limit 1;
  if v_id is null then
  else
    update public.parts set name = 'Tes Hiragana', description = 'Tes 46 Hiragana dasar: huruf ke romaji dan romaji ke huruf.', active = true, shuffle_questions = true, shuffle_options = true where id = v_id;
  end if;
  select id into v_id from public.parts where part_number = 14 limit 1;
  if v_id is null then
  else
    update public.parts set name = 'Tes Katakana', description = 'Tes 46 Katakana dasar: huruf ke romaji dan romaji ke huruf.', active = true, shuffle_questions = true, shuffle_options = true where id = v_id;
  end if;
  select id into v_id from public.parts where part_number = 15 limit 1;
  if v_id is null then
  else
    update public.parts set name = 'Tes Hiragana & Katakana', description = 'Tes gabungan 92 soal Hiragana dan Katakana dasar.', active = true, shuffle_questions = true, shuffle_options = true where id = v_id;
  end if;
end $$;


notify pgrst, 'reload schema';
